<?php include "../auth/cek_login.php";include "../koneksi.php";$id=$_GET['id'];$d=mysqli_fetch_assoc(mysqli_query($conn,"SELECT * FROM barang WHERE id=$id"));$kat=mysqli_query($conn,"SELECT * FROM kategori");if(isset($_POST['update'])){mysqli_query($conn,"UPDATE barang SET kode_barang='$_POST[kode]',nama_barang='$_POST[nama]',id_kategori='$_POST[kategori]',harga_sewa='$_POST[harga]',stok='$_POST[stok]',kondisi='$_POST[kondisi]' WHERE id=$id");header("Location:index.php");exit;} ?><!doctype html><html><head><title>Edit Barang</title><link rel="stylesheet" href="../assets/style.css"></head><body><div class="content"><h1>Edit Barang</h1><form method="post"><input name="kode" value="<?=$d['kode_barang']?>" required><input name="nama" value="<?=$d['nama_barang']?>" required><select name="kategori"><?php while($k=mysqli_fetch_assoc($kat)):?><option value="<?=$k['id']?>" <?=$k['id']==$d['id_kategori']?'selected':''?>><?=$k['nama_kategori']?></option><?php endwhile;?></select><input type="number" name="harga" value="<?=$d['harga_sewa']?>" required><input type="number" name="stok" value="<?=$d['stok']?>" required><select name="kondisi"><option <?=$d['kondisi']=='Baik'?'selected':''?>>Baik</option><option <?=$d['kondisi']=='Rusak Ringan'?'selected':''?>>Rusak Ringan</option><option <?=$d['kondisi']=='Rusak'?'selected':''?>>Rusak</option></select><button name="update">Update</button></form></div></body></html>